function minutesUntilMold(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const moldy = (r: number, c: number) => r >= 0 && c >= 0 && r < R && c < C && grid[r][c] === 2;
  let minutes = 0;
  for (;;) {
    const turn: number[][] = [];
    let fresh = 0;
    for (let r = 0; r < R; r++)
      for (let c = 0; c < C; c++)
        if (grid[r][c] === 1) {
          fresh++;
          if (moldy(r + 1, c) || moldy(r - 1, c) || moldy(r, c + 1) || moldy(r, c - 1)) turn.push([r, c]);
        }
    if (fresh === 0) return minutes;
    if (turn.length === 0) return -1;
    for (const [r, c] of turn) grid[r][c] = 2; // change after the scan so all spread at once
    minutes++;
  }
}

