function minutesUntilMold(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  let level: number[][] = [], fresh = 0;
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++) {
      if (grid[r][c] === 2) level.push([r, c]);
      else if (grid[r][c] === 1) fresh++;
    }
  let minutes = 0;
  while (level.length && fresh > 0) {
    const next: number[][] = [];
    for (const [r, c] of level) {
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] === 1) {
          grid[nr][nc] = 2;
          fresh--;
          next.push([nr, nc]);
        }
      }
    }
    minutes++; // if this level turned nothing, next is empty and we return -1 below anyway
    level = next;
  }
  return fresh === 0 ? minutes : -1;
}

